    white-space: nowrap;
    vertical-align: middle !important;
}

.print-format td {
    font-size: 12px !important;
}

.print-format th {
    font-size: 11px !important; 
    font-weight: bold !important;
    text-transform: uppercase !important;
}

.print-format .table-bordered td, .print-format .table-bordered th {
    border: 1px solid #000 !important;
}

.print-format .table-bordered {
    /*border: 1px solid #000;*/
    margin-top: -1px;
    margin-bottom: 0;
}

@page {
    size: letter landscape;
    /*padding: 1in;*/
    margin: .4in;
}
.print-format .print-subheading {
    string-set: docname content();
}

@media print {
    .print-format {
        box-sizing: border-box;
        max-height: 8.5in;
        max-width: 11in !important;
        padding: 0;
    }
    .thead-light {
        counter-reset: section;
    }
    @page {
        @bottom-right-corner {
            content: counter(section);
            font-size: 9pt !important;
            color: black;
            z-index: 999999;
        }
    }
    @page {
        @bottom-left-corner {
            content: "Pagina ";
            margin: 4px 0 4px 0;
            font-size: 8pt;
        }
    }
    div.print-footer {
        display: block;
        position: fixed;
        bottom: 0;
    }
}
@media screen {
    .print-format {
        box-sizing: border-box;
        max-width: 11in;
        max-height: 8.5in !important;
        padding: 0;
        margin: .4in !important;
